const raw = $input.first().json ?? {};
const payload = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const emails = payload.emails && typeof payload.emails === 'object' ? payload.emails : {};
const studentReceipt = emails.student_receipt && typeof emails.student_receipt === 'object' ? emails.student_receipt : null;
const staffAlert = emails.staff_alert && typeof emails.staff_alert === 'object' ? emails.staff_alert : null;

const studentToList = Array.isArray(studentReceipt?.to) ? studentReceipt.to.map((r) => r?.email).filter(Boolean) : [];
const staffToList = Array.isArray(staffAlert?.to) ? staffAlert.to.map((r) => r?.email).filter(Boolean) : [];

const hasStudentReceipt = studentToList.length > 0;
const hasStaffAlert = staffToList.length > 0;
const isValid = Boolean(payload.record_id && (hasStudentReceipt || hasStaffAlert));

return [
  {
    json: {
      is_valid: isValid,
      workflow_code: payload.workflow_code ?? 'student_request_mailtrap',
      workflow_run_id: payload.workflow_run_id ?? null,
      record_id: payload.record_id ?? null,
      reference_code: payload.reference_code ?? null,
      has_student_receipt: hasStudentReceipt,
      has_staff_alert: hasStaffAlert,
      student_to_email: studentToList[0] ?? '',
      student_subject: studentReceipt?.subject ?? '',
      student_html: studentReceipt?.html ?? '',
      student_text: studentReceipt?.text ?? '',
      student_category: studentReceipt?.category ?? 'siga-tramites-acuse',
      staff_to_emails: staffToList.join(','),
      staff_to_first_email: staffToList[0] ?? '',
      staff_subject: staffAlert?.subject ?? '',
      staff_html: staffAlert?.html ?? '',
      staff_text: staffAlert?.text ?? '',
      staff_category: staffAlert?.category ?? 'siga-tramites-secretaria',
      student_receipt: hasStudentReceipt ? studentReceipt : null,
      staff_alert: hasStaffAlert ? staffAlert : null,
    },
  },
];

