const ctx = $('Extraer Payload').first().json;

function parseMailtrapResult(res, label) {
  if (!res || typeof res !== 'object') {
    return { sent: false, ids: [], error: `Sin respuesta del nodo Mailtrap (${label})` };
  }

  const isUntouchedNoOp =
    res.is_valid === true &&
    res.workflow_code === 'student_request_mailtrap' &&
    typeof res.has_student_receipt === 'boolean' &&
    res.success === undefined &&
    res.message_ids === undefined &&
    res.messageId === undefined &&
    res.id === undefined;

  if (isUntouchedNoOp) {
    return {
      sent: false,
      ids: [],
      error: `Falta reemplazar el nodo vacío de Mailtrap (${label})`,
    };
  }

  if (res.error || res.errors || res.success === false) {
    const msg =
      (typeof res.error === 'string' ? res.error : res.error?.message) ||
      (Array.isArray(res.errors) ? res.errors.join(', ') : null) ||
      `El nodo Mailtrap (${label}) devolvió un error`;
    return { sent: false, ids: [], error: msg };
  }

  const ids = Array.isArray(res.message_ids)
    ? res.message_ids.map(String)
    : res.messageId
      ? [String(res.messageId)]
      : res.id
        ? [String(res.id)]
        : [];

  return { sent: true, ids, error: null };
}

let studentSent = false;
let studentMessageId = null;
let studentError = null;

if (ctx.has_student_receipt) {
  try {
    const studentOut = $('¿Enviar Alerta a Secretaría?').first()?.json ?? {};
    const parsed = parseMailtrapResult(studentOut, 'estudiante');
    studentSent = parsed.sent;
    studentMessageId = parsed.ids[0] ?? null;
    studentError = parsed.error;
  } catch (err) {
    studentError = err instanceof Error ? err.message : 'Error leyendo salida Mailtrap (estudiante)';
  }
}

let staffSent = false;
let staffMessageIds = [];
let staffError = null;

if (ctx.has_staff_alert) {
  try {
    const staffOut = $input.first()?.json ?? {};
    const parsed = parseMailtrapResult(staffOut, 'secretaría');
    staffSent = parsed.sent;
    staffMessageIds = parsed.ids;
    staffError = parsed.error;
  } catch (err) {
    staffError = err instanceof Error ? err.message : 'Error leyendo salida Mailtrap (secretaría)';
  }
}

const ok = (!ctx.has_student_receipt || studentSent) && (!ctx.has_staff_alert || staffSent);
const errorMessage = [studentError, staffError].filter(Boolean).join(' | ');

return [
  {
    json: {
      ok,
      workflow_run_id: ctx.workflow_run_id,
      record_id: ctx.record_id,
      reference_code: ctx.reference_code,
      student_sent: studentSent,
      student_message_id: studentMessageId,
      staff_sent: staffSent,
      staff_message_ids: staffMessageIds,
      ...(ok ? {} : { error: errorMessage || 'Fallo al despachar correo por Mailtrap' }),
    },
  },
];
